namespace AccessControl;

public sealed class AccessDecisionEngine
{
    public AccessDecision Decide(Principal? principal, Resource? resource, AccessRequest? request, IDelegationRegister delegations)
    {
        if (TryGetContextDenial(principal, resource, request, out var decision))
            return decision;

        var validPrincipal = principal!;
        var validResource = resource!;
        var validRequest = request!;

        if (TryGetRequestStateDenial(validPrincipal, validResource, validRequest, out decision))
            return decision;

        var administrator = validPrincipal.Roles.Contains("administrator");
        var operatorRole = validPrincipal.Roles.Contains("operator");
        var auditor = validPrincipal.Roles.Contains("auditor");
        var owner = validPrincipal.Id == validResource.OwnerId;
        var delegated = delegations.HasDelegation(validPrincipal.Id, validResource.Id, validRequest.Action);

        if (validRequest.BreakGlass)
            return DecideBreakGlass(administrator, validRequest.StrongAuthentication);

        if (TryGetClassificationDenial(validResource, validRequest, out decision))
            return decision;

        return DecideAction(
            validResource,
            validRequest,
            administrator,
            operatorRole,
            auditor,
            owner,
            delegated);
    }

    private static bool TryGetContextDenial(
        Principal? principal,
        Resource? resource,
        AccessRequest? request,
        out AccessDecision decision)
    {
        if (principal is null || resource is null || request is null)
        {
            decision = new AccessDecision(false, "missing-context", true);
            return true;
        }

        if (string.IsNullOrWhiteSpace(principal.Id) || string.IsNullOrWhiteSpace(resource.Id))
        {
            decision = new AccessDecision(false, "invalid-identity", true);
            return true;
        }

        if (principal.Suspended)
        {
            decision = new AccessDecision(false, "principal-suspended", true);
            return true;
        }

        if (!string.Equals(principal.TenantId, resource.TenantId, StringComparison.Ordinal))
        {
            decision = new AccessDecision(false, "tenant-mismatch", true);
            return true;
        }

        decision = default!;
        return false;
    }

    private static bool TryGetRequestStateDenial(
        Principal principal,
        Resource resource,
        AccessRequest request,
        out AccessDecision decision)
    {
        if (resource.Locked && request.Action != "read")
        {
            decision = new AccessDecision(false, "resource-locked", true);
            return true;
        }

        if (request.MinuteOfDay is < 0 or > 1439)
        {
            decision = new AccessDecision(false, "invalid-time", true);
            return true;
        }

        if (principal.FailedChallenges >= 3 && !request.StrongAuthentication)
        {
            decision = new AccessDecision(false, "challenge-required", true);
            return true;
        }

        decision = default!;
        return false;
    }

    private static AccessDecision DecideBreakGlass(bool administrator, bool strongAuthentication)
    {
        if (!administrator || !strongAuthentication)
            return new AccessDecision(false, "invalid-break-glass", true);

        return new AccessDecision(true, "break-glass", true);
    }

    private static bool TryGetClassificationDenial(
        Resource resource,
        AccessRequest request,
        out AccessDecision decision)
    {
        if (resource.Classification == "restricted" && !request.StrongAuthentication)
        {
            decision = new AccessDecision(false, "strong-authentication-required", true);
            return true;
        }

        if (resource.Classification == "restricted" && request.NetworkZone != "trusted")
        {
            decision = new AccessDecision(false, "trusted-network-required", true);
            return true;
        }

        decision = default!;
        return false;
    }

    private static AccessDecision DecideAction(
        Resource resource,
        AccessRequest request,
        bool administrator,
        bool operatorRole,
        bool auditor,
        bool owner,
        bool delegated)
    {
        return request.Action switch
        {
            "delete" => DecideDelete(resource, request, administrator, delegated),
            "write" => DecideWrite(resource, request, administrator, operatorRole, owner, delegated),
            "read" => DecideRead(resource, request, administrator, operatorRole, auditor, owner, delegated),
            _ => new AccessDecision(false, "unknown-action", true)
        };
    }

    private static AccessDecision DecideDelete(
        Resource resource,
        AccessRequest request,
        bool administrator,
        bool delegated)
    {
        if (!administrator)
            return new AccessDecision(false, "administrator-required", true);

        return CreateAllowedDecision(resource, request, delegated);
    }

    private static AccessDecision DecideWrite(
        Resource resource,
        AccessRequest request,
        bool administrator,
        bool operatorRole,
        bool owner,
        bool delegated)
    {
        if (!(administrator || operatorRole || owner || delegated))
            return new AccessDecision(false, "write-not-authorised", true);

        return CreateAllowedDecision(resource, request, delegated);
    }

    private static AccessDecision DecideRead(
        Resource resource,
        AccessRequest request,
        bool administrator,
        bool operatorRole,
        bool auditor,
        bool owner,
        bool delegated)
    {
        if (!(administrator || operatorRole || auditor || owner || delegated))
            return new AccessDecision(false, "read-not-authorised", false);

        return CreateAllowedDecision(resource, request, delegated);
    }

    private static AccessDecision CreateAllowedDecision(
        Resource resource,
        AccessRequest request,
        bool delegated)
    {
        var outsideBusinessHours = request.MinuteOfDay < 480 || request.MinuteOfDay > 1080;
        return new AccessDecision(
            true,
            delegated ? "delegated" : "role-or-ownership",
            outsideBusinessHours || resource.Classification == "restricted");
    }
}
